def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def safe_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, int) and isinstance(b, int):
                return a, b
        return default

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_list(v):
        return v if isinstance(v, list) else []

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pair(observation.get("self_position"), (0, 0))
    ox, oy = safe_pair(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [
            (0, 0),
            (0, gh - 1 if gh else 0),
            (gw - 1 if gw else 0, 0),
            (gw - 1 if gw else 0, gh - 1 if gh else 0),
        ]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan(c, opp_pos)
            if d > best:
                best = d
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells"))
        if not targets:
            targets = safe_list(observation.get("opponent_territory"))
        if targets:
            best = None
            best_d = None
            for item in targets:
                p = safe_pair(item, None)
                if p is None:
                    continue
                d = manhattan(self_pos, p)
                if best is None or d < best_d:
                    best = p
                    best_d = d
            if best is not None:
                return step_toward(self_pos, best)
        cx = (gw - 1) // 2 if gw else sx
        cy = (gh - 1) // 2 if gh else sy
        return step_toward(self_pos, (cx, cy))

    resources = safe_list(observation.get("resources"))
    if resources:
        best = None
        best_d = None
        for item in resources:
            p = safe_pair(item, None)
            if p is None:
                continue
            d = manhattan(self_pos, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        if best is not None:
            return step_toward(self_pos, best)

    # Default: move away from opponent if possible, otherwise toward center-ish.
    away = (sx - ox, sy - oy)
    if away[0] == 0 and away[1] == 0:
        away = (1, 0)
    return [clamp_step(away[0]), clamp_step(away[1])]

